parameters.jsCode:
const body = $json.body || {};
const note = body.note || body.text || '';
const source = body.source || 'manual';
const token = body.token || '';
if (!note.trim()) throw new Error('Memory note is required.');
if (($env.MEMORY_CAPTURE_TOKEN || '').trim() && token !== $env.MEMORY_CAPTURE_TOKEN) throw new Error('Unauthorized memory capture request.');
const stamp = new Date().toISOString();
const slug = stamp.replace(/[:.]/g, '-');
return [{ json: { note, source, stamp, slug } }];

parameters.command:
mkdir -p /data/assistant-memory/inbox/raw && cat > /data/assistant-memory/inbox/raw/{{$json.slug}}.md <<'EOF'
# Memory Capture

- Captured at: {{$json.stamp}}
- Source: {{$json.source}}

## Raw Note

{{$json.note}}
EOF

parameters.jsonBody:
={
  "model": $env.OLLAMA_SUMMARY_MODEL || "qwen2.5:7b-instruct-q4_K_M",
  "stream": false,
  "prompt": "Classify and summarize this personal memory note for a local assistant. Return markdown with these headings exactly: Summary, Durability, TargetFile, ProposedUpdate. TargetFile must be one of identity_and_preferences.md, current_projects.md, active_decisions.md, environment_and_tools.md, recent_context_summary.md. Keep it concise and do not invent details.\n\nNote:\n" + $node['Validate Request'].json.note
}

parameters.jsCode:
const raw = $node['Validate Request'].json;
const response = $json.response || '';
const fileMatch = response.match(/TargetFile\s*\n+([^\n]+)/i);
const targetFile = (fileMatch?.[1] || 'recent_context_summary.md').trim().replace(/^[-*]\s*/, '');
const allowed = new Set(['identity_and_preferences.md','current_projects.md','active_decisions.md','environment_and_tools.md','recent_context_summary.md']);
const safeFile = allowed.has(targetFile) ? targetFile : 'recent_context_summary.md';
const appendix = `\n\n## Captured ${raw.stamp}\n\n${response}\n`;
return [{ json: { ...raw, response, safeFile, appendix, filePath: `/data/assistant-memory/memory/${safeFile}` } }];

parameters.command:
mkdir -p /data/assistant-memory/memory /data/assistant-memory/inbox/processed && cat >> /data/assistant-memory/memory/{{$json.safeFile}} <<'EOF'
{{$json.appendix}}
EOF
cat > /data/assistant-memory/inbox/processed/{{$json.slug}}.md <<'EOF'
# Processed Memory Capture

- Captured at: {{$json.stamp}}
- Source: {{$json.source}}
- Target file: {{$json.safeFile}}

{{$json.response}}
EOF
